import sys
def main():
    data = sys.stdin.read().split()
    n, k = int(data[0]), int(data[1])
    a = [[int(data[2 + i * n + j]) for j in range(n)] for i in range(n)]
    lo, hi = a[0][0], a[n - 1][n - 1]
    def count_le(x):
        c, j = 0, n - 1
        for i in range(n):
            while j >= 0 and a[i][j] > x:
                j -= 1
            if j < 0:
                break
            c += j + 1
        return c
    while lo < hi:
        mid = (lo + hi) // 2
        if count_le(mid) >= k:
            hi = mid
        else:
            lo = mid + 1
    print(lo)
main()

